/**
 * Cloudflare Worker entry:
 *  - serves static build files (/_next/static, /flags, …) from Workers KV (see scripts/cf-upload-assets.mjs),
 *  - forwards everything else to the OpenNext-generated Next.js handler,
 *  - runs the business automations hourly through a Cron Trigger.
 */
// @ts-expect-error — generated by `opennextjs-cloudflare build`
import nextWorker from "./.open-next/worker.js";

type KV = { getWithMetadata(key: string, type: "arrayBuffer"): Promise<{ value: ArrayBuffer | null; metadata: { ct?: string } | null }> };
type Env = { CRON_SECRET?: string; APP_URL?: string; STATIC_ASSETS?: KV; [k: string]: unknown };
type Ctx = { waitUntil(p: Promise<unknown>): void };

const STATIC_PREFIXES = ["/_next/static/", "/flags/", "/brand/"];

async function serveAsset(env: Env, pathname: string): Promise<Response | null> {
  if (!env.STATIC_ASSETS) return null;
  const { value, metadata } = await env.STATIC_ASSETS.getWithMetadata(decodeURIComponent(pathname), "arrayBuffer");
  if (!value) return null;
  const immutable = pathname.startsWith("/_next/static/");
  return new Response(value, {
    headers: {
      "Content-Type": metadata?.ct || "application/octet-stream",
      "Cache-Control": immutable ? "public, max-age=31536000, immutable" : "public, max-age=86400",
      "X-Content-Type-Options": "nosniff",
    },
  });
}

// OpenNext may call env.ASSETS.fetch(); back it with the same KV store.
function withAssets(env: Env): Env {
  return {
    ...env,
    ASSETS: {
      fetch: async (input: Request | string) => {
        const url = new URL(typeof input === "string" ? input : input.url);
        return (await serveAsset(env, url.pathname)) ?? new Response("Not found", { status: 404 });
      },
    },
  };
}

export default {
  async fetch(request: Request, env: Env, ctx: Ctx) {
    const { pathname } = new URL(request.url);
    if ((request.method === "GET" || request.method === "HEAD") && STATIC_PREFIXES.some((p) => pathname.startsWith(p))) {
      const asset = await serveAsset(env, pathname);
      return asset ?? new Response("Not found", { status: 404 });
    }
    return nextWorker.fetch(request, withAssets(env), ctx);
  },

  async scheduled(_event: unknown, env: Env, ctx: Ctx) {
    const base = (env.APP_URL || "https://localhost").replace(/\/$/, "");
    const req = new Request(`${base}/api/cron/run`, { headers: { authorization: `Bearer ${env.CRON_SECRET}` } });
    ctx.waitUntil(
      nextWorker.fetch(req, withAssets(env), ctx).then(async (res: Response) => {
        if (!res.ok) console.error("[cron] automation run failed", res.status, await res.text());
      }),
    );
  },
};
